# execute in generator namespace
T=[]
def task(g,title,context,req,sql,grain,error,steps,difficulty=None):
 T.append(dict(projectId=g,title=title,context=context,requirements=req,sql=sql,grain=grain,commonError=error,executionSteps=steps.split('；'),difficulty=difficulty or ('中等' if len([t for t in T if t['projectId']==g])==0 else '挑战' if len([t for t in T if t['projectId']==g])==4 else '困难')))
M="SUBSTR(order_date,1,7)"; Y="order_date BETWEEN '2025-01-01' AND '2025-12-31'"; Q="order_date BETWEEN '2025-10-01' AND '2025-12-31'"; C="'2025-12-31'"
task('retail','门店净销售、利润与目标达成','区域经理需要2025年门店经营表。','每门店一行；有效线下订单，按原订单日期归属截至年底退货；毛利=净销售-退货冲减后成本；毛利率和目标达成率使用百分比，分母为0返回NULL；金额单位分。保留无销售门店。',f"WITH a AS (SELECT store_id,SUM(net_cents) net,SUM(cost_cents) cost FROM v_sales_lines WHERE channel='store' AND {Y} GROUP BY store_id), b AS (SELECT store_id,SUM(target_cents) target FROM sales_targets WHERE month_key BETWEEN '2025-01' AND '2025-12' GROUP BY store_id) SELECT s.store_id,COALESCE(a.net,0) net_cents,COALESCE(a.net-a.cost,0) gross_cents,ROUND(100.0*(a.net-a.cost)/NULLIF(a.net,0),2) margin_pct,b.target target_cents,ROUND(100.0*COALESCE(a.net,0)/NULLIF(b.target,0),2) achievement_pct FROM stores s LEFT JOIN a ON a.store_id=s.store_id LEFT JOIN b ON b.store_id=s.store_id ORDER BY s.store_id",'门店','直接连接月目标与订单明细会重复累计目标。','先按门店聚合销售与成本；独立累计目标；左连接门店；计算比率')
task('retail','门店月度环比同比与持续下滑','经营主管希望识别连续三个月环比负增长的门店。','构造2023—2025完整门店月份轴；2025年逐月返回净销售、环比、同比及连续三月负增长标志；上期零或缺失时比率NULL。',"WITH m AS (SELECT DISTINCT month_key FROM calendar_days), a AS (SELECT store_id,SUBSTR(order_date,1,7) m,SUM(net_cents) net FROM v_sales_lines WHERE channel='store' GROUP BY store_id,SUBSTR(order_date,1,7)), b AS (SELECT s.store_id,m.month_key,COALESCE(a.net,0) net FROM stores s CROSS JOIN m LEFT JOIN a ON a.store_id=s.store_id AND a.m=m.month_key), p AS (SELECT *,LAG(net) OVER(PARTITION BY store_id ORDER BY month_key) prev,LAG(net,12) OVER(PARTITION BY store_id ORDER BY month_key) prior_year FROM b), q AS (SELECT *,CASE WHEN prev>0 AND net<prev THEN 1 ELSE 0 END falling FROM p), z AS (SELECT *,SUM(falling) OVER(PARTITION BY store_id ORDER BY month_key ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) fall3 FROM q) SELECT store_id,month_key,net net_cents,ROUND(100.0*(net-prev)/NULLIF(prev,0),2) mom_pct,ROUND(100.0*(net-prior_year)/NULLIF(prior_year,0),2) yoy_pct,CASE WHEN fall3=3 THEN 1 ELSE 0 END three_declines FROM z WHERE month_key>='2025-01' ORDER BY store_id,month_key",'门店×月','先筛2025再计算窗口会丢失去年和上月。','构造月份轴；汇总销售并补零；计算两个历史窗口；滚动检查连续下滑；最后筛2025')
task('retail','高销售低毛利商品诊断','商品经理不希望销售额掩盖利润问题。','2025年线下商品净销售额位于前四分之一且毛利率低于30%；返回销售、毛利率、折扣额、退款额；按净销售降序、商品编号升序。四分位使用NTILE(4)，并列按编号。',f"WITH a AS (SELECT product_id,SUM(net_cents) net,SUM(cost_cents) cost,SUM(discount_cents) discount,SUM(refund_cents) refund FROM v_sales_lines WHERE channel='store' AND {Y} GROUP BY product_id), b AS (SELECT *,NTILE(4) OVER(ORDER BY net DESC,product_id) bucket FROM a) SELECT product_id,net net_cents,ROUND(100.0*(net-cost)/NULLIF(net,0),2) margin_pct,discount discount_cents,refund refund_cents FROM b WHERE bucket=1 AND 100.0*(net-cost)/NULLIF(net,0)<30 ORDER BY net DESC,product_id",'商品','先按毛利筛选再计算销售四分位改变总体。','按商品独立汇总；按全体净额分箱；应用毛利阈值；输出折扣退款')
task('retail','促销与非促销的日均表现','促销期天数不同，不能直接用总额比较。','2025年线下订单，按日期是否落在任一促销区间分组；计算日均净销售、日均净件数、毛利率；日数来自完整日历，包含零销售日；不将相关性解释为因果。',"WITH d AS (SELECT day,CASE WHEN EXISTS(SELECT 1 FROM promotions p WHERE day BETWEEN p.start_date AND p.end_date) THEN 1 ELSE 0 END promo FROM calendar_days WHERE day BETWEEN '2025-01-01' AND '2025-12-31'), a AS (SELECT order_date,SUM(net_cents) net,SUM(net_qty) qty,SUM(cost_cents) cost FROM v_sales_lines WHERE channel='store' AND order_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY order_date) SELECT d.promo,COUNT(*) days,ROUND(1.0*SUM(COALESCE(a.net,0))/COUNT(*),2) daily_net_cents,ROUND(1.0*SUM(COALESCE(a.qty,0))/COUNT(*),2) daily_units,ROUND(100.0*SUM(a.net-a.cost)/NULLIF(SUM(a.net),0),2) margin_pct FROM d LEFT JOIN a ON a.order_date=d.day GROUP BY d.promo ORDER BY d.promo",'促销状态','按订单数除总额得到客单价而不是日均。','日历标记促销日；独立日级汇总；补全日历；计算日均及加权毛利率')
task('retail','门店综合经营异常看板','管理层需要优先检查经营异常的门店。','2025年第四季度，门店净销售、毛利率、目标达成率、退款率（退款/退款前折后销售额）、净销售排名；异常项：毛利率<30%、达成率<90%、退款率>8%；按异常数降序。',f"WITH a AS (SELECT store_id,SUM(net_cents) net,SUM(cost_cents) cost,SUM(refund_cents) refund FROM v_sales_lines WHERE channel='store' AND {Q} GROUP BY store_id), b AS (SELECT store_id,SUM(target_cents) target FROM sales_targets WHERE month_key BETWEEN '2025-10' AND '2025-12' GROUP BY store_id), p AS (SELECT s.store_id,COALESCE(a.net,0) net,100.0*(a.net-a.cost)/NULLIF(a.net,0) margin,100.0*COALESCE(a.net,0)/NULLIF(b.target,0) attainment,100.0*a.refund/NULLIF(a.net+a.refund,0) refund_rate FROM stores s LEFT JOIN a ON a.store_id=s.store_id LEFT JOIN b ON b.store_id=s.store_id), z AS (SELECT *,CASE WHEN margin<30 THEN 1 ELSE 0 END+CASE WHEN attainment<90 THEN 1 ELSE 0 END+CASE WHEN refund_rate>8 THEN 1 ELSE 0 END flags,RANK() OVER(ORDER BY net DESC) sales_rank FROM p) SELECT store_id,net net_cents,ROUND(margin,2) margin_pct,ROUND(attainment,2) achievement_pct,ROUND(refund_rate,2) refund_pct,flags,sales_rank FROM z ORDER BY flags DESC,store_id",'门店','阈值用四舍五入后的比率可能误判边界。','按门店汇总经营指标；独立关联季度目标；用未舍入比率标记；窗口排名')
task('inventory','低销量高库存诊断','仓储经理希望优先处理积压货品。','统计2025-10-03至12-31共90日仓库销售出库量；期末为12-31；有效商品、库存价值超过500000分且销量低于20件；无销售记0，库存覆盖天数无销售返回NULL。',"WITH s AS (SELECT warehouse_id,product_id,SUM(-quantity_delta) sold FROM stock_movements WHERE movement_type='sale' AND movement_date BETWEEN '2025-10-03' AND '2025-12-31' GROUP BY warehouse_id,product_id) SELECT i.warehouse_id,i.product_id,i.quantity,COALESCE(s.sold,0) sold_units,i.quantity*i.unit_cost_cents stock_value_cents,ROUND(90.0*i.quantity/NULLIF(s.sold,0),2) cover_days FROM inventory_snapshots i JOIN products p ON p.product_id=i.product_id LEFT JOIN s ON s.warehouse_id=i.warehouse_id AND s.product_id=i.product_id WHERE p.active=1 AND i.snapshot_date='2025-12-31' AND i.quantity*i.unit_cost_cents>500000 AND COALESCE(s.sold,0)<20 ORDER BY stock_value_cents DESC,i.warehouse_id,i.product_id",'仓库×商品','用内连接会漏掉零销售的积压商品。','汇总90天销售出库；关联期末快照与有效商品；补零并应用双阈值；计算覆盖天数')
task('inventory','类别库存周转率及周转天数','仓储部门比较不同仓库与品类的资金效率。','2025年：净销售出库成本含退货冲回；年初价值以2024-12-31快照、年末以2025-12-31快照；平均库存=两端均值；周转天数365/周转率，销售成本非正时天数NULL。',"WITH a AS (SELECT warehouse_id,p.category_id,SUM(CASE WHEN movement_type='sale' THEN -quantity_delta*unit_cost_cents WHEN movement_type='return' THEN -quantity_delta*unit_cost_cents ELSE 0 END) cogs FROM stock_movements m JOIN products p ON p.product_id=m.product_id WHERE movement_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY warehouse_id,p.category_id), b AS (SELECT warehouse_id,p.category_id,SUM(quantity*unit_cost_cents)/2.0 avg_stock FROM inventory_snapshots i JOIN products p ON p.product_id=i.product_id WHERE snapshot_date IN ('2024-12-31','2025-12-31') GROUP BY warehouse_id,p.category_id) SELECT b.warehouse_id,b.category_id,COALESCE(a.cogs,0) cogs_cents,b.avg_stock avg_stock_cents,ROUND(COALESCE(a.cogs,0)/NULLIF(b.avg_stock,0),4) turnover,CASE WHEN a.cogs>0 THEN ROUND(365.0*b.avg_stock/a.cogs,2) ELSE NULL END turnover_days FROM b LEFT JOIN a ON a.warehouse_id=b.warehouse_id AND a.category_id=b.category_id ORDER BY b.warehouse_id,b.category_id",'仓库×类别','销售额不是出库成本；逐商品周转率的简单平均也不是类别周转率。','分别汇总期间净成本和两端快照；连接相同粒度；计算比例及周转天数')
task('inventory','销售速度与采购周期缺货风险','补货主管需要找出采购尚未到货时可能售罄的商品。','截止2025年底，近30天销售出库速度；供应商历史实际收货周期按合格收货量加权（使用完整2025年收货记录），无记录则14天；预计需要库存=日均出库×历史周期；仅有效商品且预计需求超过当前库存。',"WITH s AS (SELECT warehouse_id,product_id,SUM(-quantity_delta) sold FROM stock_movements WHERE movement_type='sale' AND movement_date BETWEEN '2025-12-02' AND '2025-12-31' GROUP BY warehouse_id,product_id), l AS (SELECT p.warehouse_id,i.product_id,SUM((b.day_index-a.day_index)*(g.quantity_received-g.quantity_rejected))*1.0/NULLIF(SUM(g.quantity_received-g.quantity_rejected),0) lead_days FROM goods_receipts g JOIN purchase_order_items i ON i.po_item_id=g.po_item_id JOIN purchase_orders p ON p.po_id=i.po_id JOIN calendar_days a ON a.day=p.order_date JOIN calendar_days b ON b.day=g.receipt_date WHERE g.receipt_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY p.warehouse_id,i.product_id), z AS (SELECT i.warehouse_id,i.product_id,i.quantity,COALESCE(s.sold,0) sold,COALESCE(l.lead_days,14) lead_days FROM inventory_snapshots i JOIN products p ON p.product_id=i.product_id LEFT JOIN s ON s.warehouse_id=i.warehouse_id AND s.product_id=i.product_id LEFT JOIN l ON l.warehouse_id=i.warehouse_id AND l.product_id=i.product_id WHERE i.snapshot_date='2025-12-31' AND p.active=1) SELECT warehouse_id,product_id,quantity,sold,ROUND(lead_days,2) lead_days,ROUND(sold*lead_days/30.0-quantity,2) expected_shortage FROM z WHERE sold*lead_days/30.0>quantity ORDER BY expected_shortage DESC,warehouse_id,product_id",'仓库×商品','把下单承诺日当实际收货日，或以0天替代缺失历史。','计算销售速度；按合格件加权实际交期；合并库存；识别预计缺口')
task('inventory','按先进先出假设推算库存库龄','仓储部门希望识别期末长期库存；本库无实物批次拣货记录，按FIFO数量推算，非实际批次审计。','将期初库存视作2023-01-01批次，收货与退货视作入库批次；累计销售出库消耗最早批次；期末剩余批次中2025-07-04及以前为≥180日；按仓库商品输出陈旧件数、陈旧金额（期末标准成本）和陈旧比例；仅有陈旧件数。',"WITH a AS (SELECT warehouse_id,product_id,'2023-01-01' d,0 seq,quantity q FROM inventory_opening WHERE quantity>0 UNION ALL SELECT warehouse_id,product_id,movement_date,movement_id,quantity_delta FROM stock_movements WHERE quantity_delta>0), b AS (SELECT *,SUM(q) OVER(PARTITION BY warehouse_id,product_id ORDER BY d,seq ROWS UNBOUNDED PRECEDING) cum FROM a), s AS (SELECT warehouse_id,product_id,SUM(-quantity_delta) sold FROM stock_movements WHERE movement_type='sale' GROUP BY warehouse_id,product_id), z AS (SELECT b.*,CASE WHEN b.cum<=COALESCE(s.sold,0) THEN 0 WHEN b.cum-b.q>=COALESCE(s.sold,0) THEN b.q ELSE b.cum-COALESCE(s.sold,0) END remain FROM b LEFT JOIN s ON s.warehouse_id=b.warehouse_id AND s.product_id=b.product_id), g AS (SELECT warehouse_id,product_id,SUM(CASE WHEN d<='2025-07-04' THEN remain ELSE 0 END) aged,SUM(remain) total FROM z GROUP BY warehouse_id,product_id) SELECT g.warehouse_id,g.product_id,g.aged aged_units,g.aged*i.unit_cost_cents aged_value_cents,ROUND(100.0*g.aged/NULLIF(g.total,0),2) aged_pct FROM g JOIN inventory_snapshots i ON i.warehouse_id=g.warehouse_id AND i.product_id=g.product_id AND i.snapshot_date='2025-12-31' WHERE g.aged>0 ORDER BY aged_value_cents DESC,g.warehouse_id,g.product_id",'仓库×商品','使用最后一次入库日期代表所有库存库龄会低估老批次。','合并期初和入库批次；累计入库数量；扣减累计出库；计算旧批次剩余；关联期末成本')
task('inventory','补货优先级与供应商风险','库存主管需要同时考虑销售速度、在途量与采购履约。','期末，未来30天需求=近30天实际销售出库量；在途=未取消且承诺日未到年底的未完成采购数量；履约风险用对应商品历史采购准时足量率（承诺日已到且非取消），缺失NULL；对有效商品计算缺口、库存金额、供应商风险，按缺口降序。',"WITH s AS (SELECT warehouse_id,product_id,SUM(-quantity_delta) sold FROM stock_movements WHERE movement_type='sale' AND movement_date BETWEEN '2025-12-02' AND '2025-12-31' GROUP BY warehouse_id,product_id), p AS (SELECT warehouse_id,product_id,SUM(CASE WHEN promised_date>'2025-12-31' AND quantity_ordered>accepted THEN quantity_ordered-accepted ELSE 0 END) inbound,SUM(CASE WHEN promised_date<='2025-12-31' AND on_time>=quantity_ordered THEN 1 ELSE 0 END) good,SUM(CASE WHEN promised_date<='2025-12-31' THEN 1 ELSE 0 END) due FROM v_po_lines GROUP BY warehouse_id,product_id), z AS (SELECT i.warehouse_id,i.product_id,i.quantity,i.quantity*i.unit_cost_cents stock_value_cents,COALESCE(s.sold,0) demand,COALESCE(p.inbound,0) inbound,100.0*p.good/NULLIF(p.due,0) reliability FROM inventory_snapshots i JOIN products a ON a.product_id=i.product_id LEFT JOIN s ON s.warehouse_id=i.warehouse_id AND s.product_id=i.product_id LEFT JOIN p ON p.warehouse_id=i.warehouse_id AND p.product_id=i.product_id WHERE i.snapshot_date='2025-12-31' AND a.active=1) SELECT warehouse_id,product_id,quantity,stock_value_cents,demand,inbound,demand-quantity-inbound shortage,ROUND(reliability,2) reliability_pct FROM z WHERE demand>quantity+inbound ORDER BY shortage DESC,warehouse_id,product_id",'仓库×商品','将已逾期未到货全部当作确定在途会掩盖风险。','分别统计销售和采购履约；筛选未来承诺在途；连接期末；排名缺口')
task('ecommerce','新老客户净收入及客单价','营销部门比较首购客户与已有购买历史的客户。','仅线上有效订单。客户首次有效订单以日期、订单编号决胜；2025年按订单是否首购分组，输出客户数、订单数、净收入和平均订单净额（分）。',f"WITH a AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY order_date,order_id) rn FROM v_order_net WHERE channel='online') SELECT CASE WHEN rn=1 THEN 'new' ELSE 'returning' END segment,COUNT(DISTINCT customer_id) customers,COUNT(*) orders,SUM(net_cents) net_cents,ROUND(1.0*SUM(net_cents)/COUNT(*),2) avg_order_cents FROM a WHERE {Y} GROUP BY CASE WHEN rn=1 THEN 'new' ELSE 'returning' END ORDER BY segment",'订单所属客户阶段','先筛2025会把已有购买客户误标为新客；客户可在两个组出现。','计算完整历史订单序号；筛选目标年；按首购标记汇总')
task('ecommerce','最近消费、频率、金额客户分层','客户运营团队需要可执行的分层名单。','2025年有线上有效购买的客户；截止12-31距最近购买天数；年度订单数和净消费金额；分别按最近日期近到远、频率高到低、金额高到低分五组（并列客户编号）；三个分数5为最好；总分≥13为高价值、≤6为低活跃。',f"WITH a AS (SELECT customer_id,MAX(order_date) last_day,COUNT(*) freq,SUM(net_cents) money FROM v_order_net WHERE channel='online' AND {Y} GROUP BY customer_id), b AS (SELECT *,6-NTILE(5) OVER(ORDER BY last_day DESC,customer_id) r_score,6-NTILE(5) OVER(ORDER BY freq DESC,customer_id) f_score,6-NTILE(5) OVER(ORDER BY money DESC,customer_id) m_score FROM a) SELECT b.customer_id,1095-d.day_index recency_days,freq,money net_cents,r_score,f_score,m_score,CASE WHEN r_score+f_score+m_score>=13 THEN 'high_value' WHEN r_score+f_score+m_score<=6 THEN 'low_activity' ELSE 'regular' END segment FROM b JOIN calendar_days d ON d.day=b.last_day ORDER BY b.customer_id",'客户','每行订单做NTILE会将同一客户拆入多组。','先按客户聚合；三种独立窗口分箱；按总分分类；计算距截止日天数')
task('ecommerce','首购月份留存矩阵','业务经理希望观察首购后的月度复购留存。','线上有效订单；首次购买月为同期群，观察第0至第6月；按首购月与月偏移输出同期群规模、活跃客户与留存率；没有活跃但已观察的月份为0，未来月份不输出。',"WITH a AS (SELECT customer_id,MIN(SUBSTR(order_date,1,7)) cohort FROM v_order_net WHERE channel='online' GROUP BY customer_id), b AS (SELECT cohort,COUNT(*) n FROM a GROUP BY cohort), m AS (SELECT DISTINCT month_key FROM calendar_days), x AS (SELECT b.cohort,m.month_key,b.n,(CAST(SUBSTR(m.month_key,1,4) AS INTEGER)-CAST(SUBSTR(b.cohort,1,4) AS INTEGER))*12+CAST(SUBSTR(m.month_key,6,2) AS INTEGER)-CAST(SUBSTR(b.cohort,6,2) AS INTEGER) k FROM b CROSS JOIN m WHERE m.month_key>=b.cohort), y AS (SELECT a.cohort,SUBSTR(o.order_date,1,7) m,COUNT(DISTINCT o.customer_id) active FROM a JOIN v_order_net o ON o.customer_id=a.customer_id AND o.channel='online' GROUP BY a.cohort,SUBSTR(o.order_date,1,7)) SELECT x.cohort,x.k month_offset,x.n cohort_size,COALESCE(y.active,0) active_customers,ROUND(100.0*COALESCE(y.active,0)/x.n,2) retention_pct FROM x LEFT JOIN y ON y.cohort=x.cohort AND y.m=x.month_key WHERE x.k BETWEEN 0 AND 6 ORDER BY x.cohort,x.k",'首购月×月偏移','直接COUNT订单会把同一客户的多次复购重复计数。','确定首购月份；构造可观测月份；去重客户；计算留存')
task('ecommerce','营销渠道转化与获客成本','营销负责人希望评估不同渠道效率。','2025年，按访问渠道归因；转化率=有有效订单的不同会话数/会话数；新客数只计历史首次线上有效订单；获客成本=渠道广告支出/新客数；净收入广告回报=净销售/广告支出；零分母NULL。',"WITH s AS (SELECT source_id,COUNT(*) sessions FROM customer_sessions WHERE session_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY source_id), o AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY order_date,order_id) rn FROM v_order_net WHERE channel='online'), a AS (SELECT t.source_id,COUNT(DISTINCT o.session_id) converted,SUM(CASE WHEN rn=1 THEN 1 ELSE 0 END) new_customers,SUM(net_cents) net FROM o JOIN customer_sessions t ON t.session_id=o.session_id WHERE o.order_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY t.source_id), p AS (SELECT source_id,SUM(spend_cents) spend FROM marketing_campaigns WHERE month_key BETWEEN '2025-01' AND '2025-12' GROUP BY source_id) SELECT t.source_id,s.sessions,COALESCE(a.converted,0) converted,ROUND(100.0*COALESCE(a.converted,0)/NULLIF(s.sessions,0),2) conversion_pct,COALESCE(a.new_customers,0) new_customers,p.spend spend_cents,ROUND(1.0*p.spend/NULLIF(a.new_customers,0),2) cac_cents,ROUND(1.0*a.net/NULLIF(p.spend,0),4) roas FROM traffic_sources t LEFT JOIN s ON s.source_id=t.source_id LEFT JOIN a ON a.source_id=t.source_id LEFT JOIN p ON p.source_id=t.source_id ORDER BY t.source_id",'渠道','广告支出不能直接连接订单明细求和；转化分母是会话不是客户。','按渠道汇总会话；历史首次购买标记；按渠道汇总转换与收入；独立汇总广告支出')
task('ecommerce','高价值流失风险客户','运营希望针对长期未购买但历史价值高的客户。','截至2025年底所有线上有效购买客户；历史订单数≥3、历史净金额排名前20%（NTILE(5)，按编号决胜）、最近90日无消费，输出历史毛利、最近购买距今天数和风险优先级（毛利降序）。',"WITH a AS (SELECT customer_id,COUNT(*) freq,MAX(order_date) last_day,SUM(net_cents) net,SUM(net_cents-cost_cents) gross FROM v_order_net WHERE channel='online' GROUP BY customer_id), b AS (SELECT *,NTILE(5) OVER(ORDER BY net DESC,customer_id) bucket FROM a) SELECT b.customer_id,freq,net net_cents,gross gross_cents,1095-d.day_index recency_days FROM b JOIN calendar_days d ON d.day=b.last_day WHERE bucket=1 AND freq>=3 AND 1095-d.day_index>=90 ORDER BY gross DESC,b.customer_id",'客户','仅凭最后消费日期无法识别高价值，且流失风险不是已流失事实。','汇总历史价值；在全体客户上分位；计算距截止日天数；筛风险名单')
task('finance','预算与实际费用差异','财务负责人检查部门年度超支。','2025年部门×费用科目，预算与费用分录各自汇总，偏差=实际-预算；超过预算10%标记；保留有预算但没有发生额的项目；分母为零返回NULL。',"WITH b AS (SELECT department_id,account_id,SUM(budget_cents) budget FROM budgets WHERE month_key BETWEEN '2025-01' AND '2025-12' GROUP BY department_id,account_id), a AS (SELECT department_id,account_id,SUM(expense_cents) actual FROM v_expenses WHERE entry_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY department_id,account_id) SELECT b.department_id,b.account_id,b.budget budget_cents,COALESCE(a.actual,0) actual_cents,COALESCE(a.actual,0)-b.budget variance_cents,ROUND(100.0*(COALESCE(a.actual,0)-b.budget)/NULLIF(b.budget,0),2) variance_pct,CASE WHEN COALESCE(a.actual,0)>b.budget*1.1 THEN 1 ELSE 0 END over_budget FROM b LEFT JOIN a ON a.department_id=b.department_id AND a.account_id=b.account_id ORDER BY b.department_id,b.account_id",'部门×科目','预算按月存在，连接分录后再求和会放大预算。','预算单独聚合；费用独立聚合；合并并计算差异')
task('finance','供应商发票与付款核对','财务人员需要年底未付及异常付款清单。','所有截至12-31的供应商发票，汇总付款；输出发票金额、实付金额、余额和未付/部分/足额/超额状态。按余额倒序。',"SELECT supplier_invoice_id,supplier_id,billed_cents,paid_cents,balance_cents,CASE WHEN paid_cents=0 THEN 'unpaid' WHEN balance_cents>0 THEN 'partial' WHEN balance_cents=0 THEN 'paid' ELSE 'overpaid' END payment_state FROM v_invoice_balance ORDER BY balance_cents DESC,supplier_invoice_id",'发票','不能直接将多笔付款与多行发票明细同时连接后求和。','先检查发票行与付款的预聚合视图；比较金额与余额；分类')
task('finance','应付账款账龄','财务负责人评估逾期支付压力。','截至2025-12-31，余额>0；按到期日分为未逾期（到期日≥截止日）、1—30、31—60、61—90、90日以上；按供应商与账龄汇总发票数及应付余额。日期差用日历索引；到期日可能超出年底，先判未逾期。',"WITH a AS (SELECT v.*,CASE WHEN due_date>='2025-12-31' THEN 'current' WHEN due_date>='2025-12-01' THEN '01-30' WHEN due_date>='2025-11-01' THEN '31-60' WHEN due_date>='2025-10-02' THEN '61-90' ELSE '90+' END bucket FROM v_invoice_balance v WHERE balance_cents>0) SELECT supplier_id,bucket,COUNT(*) invoices,SUM(balance_cents) outstanding_cents FROM a GROUP BY supplier_id,bucket ORDER BY supplier_id,bucket",'供应商×账龄','账龄基于到期日，不是发票日期；未到期不能算逾期。','先取截止日余额；按固定日期边界分箱；聚合供应商应付')
task('finance','银行流水与凭证全量对账','审计人员需要同时寻找银行端和账簿端的未匹配。','2025年费用凭证（按reference_no）与银行支出绝对值（按reference_no）分别汇总；采用全量键集合；空银行参考号使用每笔流水独立键；输出存在缺失或差异的记录及差额（银行-账簿）。',"WITH a AS (SELECT reference_no ref,SUM(expense_cents) ledger FROM v_expenses WHERE entry_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY reference_no), b AS (SELECT COALESCE(reference_no,CONCAT('BANK-',bank_id)) ref,SUM(-amount_cents) bank FROM bank_transactions WHERE transaction_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY COALESCE(reference_no,CONCAT('BANK-',bank_id))), k AS (SELECT ref FROM a UNION SELECT ref FROM b) SELECT k.ref,a.ledger ledger_cents,b.bank bank_cents,COALESCE(b.bank,0)-COALESCE(a.ledger,0) difference_cents,CASE WHEN a.ref IS NULL THEN 'bank_only' WHEN b.ref IS NULL THEN 'ledger_only' ELSE 'difference' END issue FROM k LEFT JOIN a ON a.ref=k.ref LEFT JOIN b ON b.ref=k.ref WHERE a.ref IS NULL OR b.ref IS NULL OR a.ledger<>b.bank ORDER BY k.ref",'对账参考号','内连接无法找出缺失记录；NULL参考号不可合并成一笔。','按两端参考号汇总；构造全量键；左连接两端；筛选差异')
task('finance','多规则异常交易筛查','审计部门需要异常线索，不用于认定违规。','发票粒度；同一供应商同编号重复、金额超过供应商平均发票金额2倍、超额付款、账单金额与对应采购行按收货计价相差超过100分；每条发票计算异常数，至少一个标记。发票单价或数量差异需复核。',"WITH a AS (SELECT v.*,COUNT(*) OVER(PARTITION BY supplier_id,invoice_no) copies,AVG(billed_cents) OVER(PARTITION BY supplier_id) avg_bill FROM v_invoice_balance v), b AS (SELECT po_id,SUM(accepted*unit_price_cents) expected FROM v_po_lines GROUP BY po_id), z AS (SELECT a.*,CASE WHEN copies>1 THEN 1 ELSE 0 END duplicate_flag,CASE WHEN billed_cents>2*avg_bill THEN 1 ELSE 0 END large_flag,CASE WHEN balance_cents<0 THEN 1 ELSE 0 END overpay_flag,CASE WHEN ABS(billed_cents-COALESCE(b.expected,0))>100 THEN 1 ELSE 0 END mismatch_flag FROM a LEFT JOIN b ON b.po_id=a.po_id) SELECT supplier_invoice_id,supplier_id,billed_cents,duplicate_flag,large_flag,overpay_flag,mismatch_flag,duplicate_flag+large_flag+overpay_flag+mismatch_flag flags FROM z WHERE duplicate_flag+large_flag+overpay_flag+mismatch_flag>0 ORDER BY flags DESC,supplier_invoice_id",'发票（本模拟每采购单至多一张正常发票；重复异常专用）','对每张发票使用整个采购单金额只有本模拟的一单一正常发票假设成立。','窗口计算供应商基准；独立汇总收货金额；构造四个标志；输出候选')
task('hr','月末人员规模与变动','人资经理需要2025年部门月末人数和上月变化。','任职历史使用左闭右开区间；2024-12至2025-12构建部门月末轴，月末人数及净变化；最终输出2025年。调动计入所属部门变化，不等于离职。',"WITH m AS (SELECT month_key,MAX(day) last_day FROM calendar_days WHERE month_key>='2024-12' GROUP BY month_key), a AS (SELECT d.department_id,m.month_key,COUNT(h.employee_id) headcount FROM departments d CROSS JOIN m LEFT JOIN employment_history h ON h.department_id=d.department_id AND h.start_date<=m.last_day AND (h.end_date IS NULL OR h.end_date>m.last_day) GROUP BY d.department_id,m.month_key), b AS (SELECT *,LAG(headcount) OVER(PARTITION BY department_id ORDER BY month_key) prev FROM a) SELECT department_id,month_key,headcount,headcount-prev net_change FROM b WHERE month_key>='2025-01' ORDER BY department_id,month_key",'部门×月','用当前部门回填历史月份会错计调动。','构造月末轴；匹配生效任职；计算前月人数；保留2025')
task('hr','月度离职率与趋势','人资经理比较各部门真实离职率。','2025年每部门每月真实离职人数（终止日期落月内，取终止前岗位）/期初期末平均在职数；期初以当月首日之前一天在职为准；滚动三月率用离职总数/三个月平均人数之和，非简单平均。',"WITH m AS (SELECT month_key,MIN(day) first_day,MAX(day) last_day,MIN(day_index) first_idx FROM calendar_days WHERE month_key>='2025-01' GROUP BY month_key), a AS (SELECT d.department_id,m.month_key,SUM(CASE WHEN h.start_date< m.first_day AND (h.end_date IS NULL OR h.end_date>=m.first_day) THEN 1 ELSE 0 END) opening,SUM(CASE WHEN h.start_date<=m.last_day AND (h.end_date IS NULL OR h.end_date>m.last_day) THEN 1 ELSE 0 END) closing,SUM(CASE WHEN e.termination_date BETWEEN m.first_day AND m.last_day AND h.end_date=e.termination_date THEN 1 ELSE 0 END) exits FROM departments d CROSS JOIN m LEFT JOIN employment_history h ON h.department_id=d.department_id LEFT JOIN employees e ON e.employee_id=h.employee_id GROUP BY d.department_id,m.month_key), b AS (SELECT *, (opening+closing)/2.0 avg_h FROM a), z AS (SELECT *,SUM(exits) OVER(PARTITION BY department_id ORDER BY month_key ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) e3,SUM(avg_h) OVER(PARTITION BY department_id ORDER BY month_key ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) h3,COUNT(*) OVER(PARTITION BY department_id ORDER BY month_key ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) n3 FROM b) SELECT department_id,month_key,opening,closing,exits,ROUND(100.0*exits/NULLIF(avg_h,0),2) exit_pct,CASE WHEN n3=3 THEN ROUND(100.0*e3/NULLIF(h3,0),2) ELSE NULL END rolling_pct FROM z ORDER BY department_id,month_key",'部门×月','把部门调动当离职会夸大离职率。','从历史岗位重建人数；匹配真正终止；计算月率及加权滚动率')
task('hr','同岗位薪资分布与异常','薪酬分析师需要同部门同岗位的横向基准。','2025-12实发基础薪资；同部门同职位至少3人；计算组均值、排名以及偏离均值超过15%的员工；异常仅表示复核候选。',"WITH a AS (SELECT employee_id,department_id,position_id,base_cents,AVG(base_cents) OVER(PARTITION BY department_id,position_id) avg_base,COUNT(*) OVER(PARTITION BY department_id,position_id) n,RANK() OVER(PARTITION BY department_id,position_id ORDER BY base_cents DESC) salary_rank FROM v_staff_month WHERE month_key='2025-12') SELECT employee_id,department_id,position_id,base_cents,ROUND(avg_base,2) avg_base_cents,salary_rank,ROUND(100.0*(base_cents-avg_base)/NULLIF(avg_base,0),2) deviation_pct FROM a WHERE n>=3 AND ABS(base_cents-avg_base)>avg_base*.15 ORDER BY department_id,position_id,salary_rank,employee_id",'员工×月','比较全部员工薪资忽略岗位、职级和部门。','确定薪资期间；按可比组窗口计算；筛选足够样本与偏差')
task('hr','部门人力成本与加班','财务与人资联合分析部门第四季度人工成本。','按员工月薪归属岗位；基础薪资+奖金+估算加班费（每月176小时、1.5倍基础时薪，按分钟；逐员工月四舍五入到分）；统计部门×月成本、工时与加班，成本每出勤小时。',"SELECT department_id,month_key,SUM(base_cents) base_cents,SUM(bonus_cents) bonus_cents,SUM(overtime_minutes) overtime_minutes,SUM(labor_cents) labor_cents,ROUND(60.0*SUM(labor_cents)/NULLIF(SUM(worked_minutes+overtime_minutes),0),2) cost_per_hour_cents FROM v_staff_month WHERE month_key BETWEEN '2025-10' AND '2025-12' GROUP BY department_id,month_key ORDER BY department_id,month_key",'部门×月','连接每日考勤后直接求月薪会重复累计；估算工资不代表实际法定工资。','从员工月成本视图核对计算规则；汇总部門及月份；按总工时计算成本')
task('hr','入职同期群90及180日留任','人资部门希望判断不同入职部门的新人留任。','以首次任职部门为入职部门；按入职季度与部门分组；只纳入截至2025年底已有90/180日观察期的员工；终止日等于观察日算不在职；返回两个分母和留任率。',"WITH a AS (SELECT e.employee_id,h.department_id,e.hire_date,e.termination_date,d.day_index hire_idx,t.day_index term_idx,CONCAT(SUBSTR(e.hire_date,1,4),'-Q',CASE WHEN SUBSTR(e.hire_date,6,2)<='03' THEN '1' WHEN SUBSTR(e.hire_date,6,2)<='06' THEN '2' WHEN SUBSTR(e.hire_date,6,2)<='09' THEN '3' ELSE '4' END) cohort FROM employees e JOIN employment_history h ON h.employee_id=e.employee_id AND h.start_date=e.hire_date JOIN calendar_days d ON d.day=e.hire_date LEFT JOIN calendar_days t ON t.day=e.termination_date), b AS (SELECT department_id,cohort,SUM(CASE WHEN hire_idx+90<=1095 THEN 1 ELSE 0 END) n90,SUM(CASE WHEN hire_idx+90<=1095 AND (term_idx IS NULL OR term_idx>hire_idx+90) THEN 1 ELSE 0 END) r90,SUM(CASE WHEN hire_idx+180<=1095 THEN 1 ELSE 0 END) n180,SUM(CASE WHEN hire_idx+180<=1095 AND (term_idx IS NULL OR term_idx>hire_idx+180) THEN 1 ELSE 0 END) r180 FROM a GROUP BY department_id,cohort) SELECT department_id,cohort,n90,ROUND(100.0*r90/NULLIF(n90,0),2) retention90_pct,n180,ROUND(100.0*r180/NULLIF(n180,0),2) retention180_pct FROM b ORDER BY department_id,cohort",'初始部门×入职季度','把未达到观察期限的员工当作未留任会使新同期群率偏低。','确定首次岗位；计算观察资格；在各自分母上计算留任')
task('procurement','采购价格与合同、历史价格比较','采购人员检查实际采购价是否偏离合同。','2025年非取消采购行；比较合同单价、成交价及同供应商同商品上一采购行的实际单价；上一行按订单日期、行编号；输出合同差价及较上一单变动率。',"WITH a AS (SELECT i.po_item_id,p.supplier_id,i.product_id,p.order_date,i.unit_price_cents,c.unit_price_cents contract_cents,LAG(i.unit_price_cents) OVER(PARTITION BY p.supplier_id,i.product_id ORDER BY p.order_date,i.po_item_id) previous_cents FROM purchase_order_items i JOIN purchase_orders p ON p.po_id=i.po_id JOIN supplier_contracts c ON c.contract_id=i.contract_id WHERE p.status<>'cancelled') SELECT po_item_id,supplier_id,product_id,unit_price_cents,contract_cents,unit_price_cents-contract_cents contract_variance_cents,previous_cents,ROUND(100.0*(unit_price_cents-previous_cents)/NULLIF(previous_cents,0),2) change_pct FROM a WHERE order_date BETWEEN '2025-01-01' AND '2025-12-31' ORDER BY po_item_id",'采购行','简单比较未经加权的供应商总价可能混入不同商品。','连接有效合同；计算历史上一行；筛年度并比较')
task('procurement','供应商准时、完整交付与质量','采购经理比较供应商2025年到期采购行表现。','按2025年承诺到期日且非取消采购行；准时足量=截止承诺日接受数量≥订购量；完整=截至年底接受数量≥订购量；质量合格率=接受件数/实际收货件数；输出供应商及分母。',"SELECT supplier_id,COUNT(*) due_lines,ROUND(100.0*SUM(CASE WHEN on_time>=quantity_ordered THEN 1 ELSE 0 END)/COUNT(*),2) ontime_pct,ROUND(100.0*SUM(CASE WHEN accepted>=quantity_ordered THEN 1 ELSE 0 END)/COUNT(*),2) complete_pct,ROUND(100.0*SUM(accepted)/NULLIF(SUM(received),0),2) quality_pct FROM v_po_lines WHERE promised_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY supplier_id ORDER BY supplier_id",'供应商','有任意一批准时到货并不等于整行准时足量。','按采购行预聚合收货；筛已到期；分别计算两种件数履约和质量指标')
task('procurement','采购、收货、发票三方核对','采购控制人员识别数量、价格与金额差异。','2025年非取消采购行（截止年底）；输出订购、合格收货、开票数量，开票金额与合格收货按采购单价的金额差；仅数量不等或金额差不为0；未开票也需要呈现。',f"SELECT po_item_id,po_id,supplier_id,product_id,quantity_ordered,accepted,billed,billed_cents,accepted*unit_price_cents expected_cents,billed_cents-accepted*unit_price_cents variance_cents FROM v_po_lines WHERE {Y} AND (quantity_ordered<>accepted OR accepted<>billed OR billed_cents<>accepted*unit_price_cents) ORDER BY po_item_id",'采购行','收货明细与发票明细未经聚合直接连接形成多对多膨胀。','核对采购行预聚合定义；计算数量及金额差；保留未开票未收货')
task('procurement','同商品跨供应商采购价差','管理层希望看到同品不同供应商的采购单价差异。','2025年非取消采购行，同商品同供应商采购金额/订购量为加权单价；只比较有至少两家供应商商品；输出供应商加权价、最低价及相对最低价的溢价率。',f"WITH a AS (SELECT product_id,supplier_id,SUM(ordered_cents)*1.0/SUM(quantity_ordered) avg_price FROM v_po_lines WHERE {Y} GROUP BY product_id,supplier_id), b AS (SELECT *,MIN(avg_price) OVER(PARTITION BY product_id) low,COUNT(*) OVER(PARTITION BY product_id) n FROM a) SELECT product_id,supplier_id,ROUND(avg_price,2) weighted_price_cents,ROUND(low,2) low_price_cents,ROUND(100.0*(avg_price-low)/NULLIF(low,0),2) premium_pct FROM b WHERE n>=2 ORDER BY product_id,premium_pct,supplier_id",'商品×供应商','对单位价格直接AVG没有反映采购数量权重。','按每商品供应商求加权价；窗口求最低与样本数；比较价差')
task('procurement','供应商多指标综合评价','采购部门需要可解释的供应商评分。','2025年到期采购行；至少10行；准时足量率40%、完整率25%、质量合格率20%、合同价格达标率15%（实际采购价≤合同价行数/到期行数）；质量分母为0时评分NULL；输出各指标和总分，按总分降序。',"WITH a AS (SELECT v.supplier_id,COUNT(*) n,100.0*SUM(CASE WHEN v.on_time>=v.quantity_ordered THEN 1 ELSE 0 END)/COUNT(*) ot,100.0*SUM(CASE WHEN v.accepted>=v.quantity_ordered THEN 1 ELSE 0 END)/COUNT(*) fill,100.0*SUM(accepted)/NULLIF(SUM(received),0) quality,100.0*SUM(CASE WHEN v.unit_price_cents<=c.unit_price_cents THEN 1 ELSE 0 END)/COUNT(*) price_ok FROM v_po_lines v JOIN purchase_order_items i ON i.po_item_id=v.po_item_id JOIN supplier_contracts c ON c.contract_id=i.contract_id WHERE v.promised_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY v.supplier_id) SELECT supplier_id,n due_lines,ROUND(ot,2) ontime_pct,ROUND(fill,2) complete_pct,ROUND(quality,2) quality_pct,ROUND(price_ok,2) contract_pct,ROUND(.4*ot+.25*fill+.2*quality+.15*price_ok,2) score FROM a WHERE n>=10 ORDER BY score DESC,supplier_id",'供应商','不说明权重、样本门槛和缺失指标处理会使评分不可解释。','计算四项百分比；保留充足样本；加权评分；排序')
# 20 cross-business cases; explicit groups and not separate question bank
def cross(g,title,req,sql,grain,error,steps,challenge=False):task('enterprise',title,g+'联合分析：管理层要求以同一企业口径核对业务数据。',req,sql,grain,error,steps,'挑战' if challenge else '困难');T[-1]['crossGroup']=g
cross('销售＋库存','畅销缺货与滞销积压双向筛查','2025年底仓库商品；近30日毛销量≥30且库存低于15日需求为畅销风险；近30日销量≤3且库存金额≥300000分为积压；仅有效商品。',"WITH s AS (SELECT warehouse_id,product_id,SUM(-quantity_delta) sold FROM stock_movements WHERE movement_type='sale' AND movement_date BETWEEN '2025-12-02' AND '2025-12-31' GROUP BY warehouse_id,product_id), a AS (SELECT i.warehouse_id,i.product_id,i.quantity,i.quantity*i.unit_cost_cents value_cents,COALESCE(s.sold,0) sold FROM inventory_snapshots i JOIN products p ON p.product_id=i.product_id LEFT JOIN s ON s.warehouse_id=i.warehouse_id AND s.product_id=i.product_id WHERE i.snapshot_date='2025-12-31' AND p.active=1) SELECT warehouse_id,product_id,quantity,sold,value_cents,CASE WHEN sold>=30 AND quantity<sold*.5 THEN 'fast_shortage' ELSE 'slow_excess' END issue FROM a WHERE (sold>=30 AND quantity<sold*.5) OR (sold<=3 AND value_cents>=300000) ORDER BY issue,value_cents DESC,warehouse_id,product_id",'仓库×商品','把门店库存与仓库库存混为一谈。','汇总仓库实际出库；连接期末；应用两套互斥规则')
cross('销售＋库存','商品销售贡献与库存资金占用错配','2025年按商品汇总所有渠道净销售，年底各仓库存总价值；计算两个全局份额和差值（库存占比-销售占比），保留全部商品，按差值倒序。',"WITH a AS (SELECT product_id,SUM(net_cents) net FROM v_sales_lines WHERE order_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY product_id), b AS (SELECT product_id,SUM(quantity*unit_cost_cents) stock FROM inventory_snapshots WHERE snapshot_date='2025-12-31' GROUP BY product_id), z AS (SELECT p.product_id,COALESCE(a.net,0) net,COALESCE(b.stock,0) stock FROM products p LEFT JOIN a ON a.product_id=p.product_id LEFT JOIN b ON b.product_id=p.product_id), q AS (SELECT *,100.0*net/NULLIF(SUM(net) OVER(),0) sales_share,100.0*stock/NULLIF(SUM(stock) OVER(),0) stock_share FROM z) SELECT product_id,net net_cents,stock stock_cents,ROUND(sales_share,4) sales_pct,ROUND(stock_share,4) stock_pct,ROUND(stock_share-sales_share,4) gap_points FROM q ORDER BY gap_points DESC,product_id",'商品','只用有销售的商品作为库存分母会漏掉滞销。','分别汇总销售和库存；补全商品；窗口求总量；比较份额')
cross('销售＋库存','跨仓库存调拨候选','2025年底，每仓每商品库存超过近30日销量两倍且至少多10件为供给；库存低于同期间销量为需求。按商品匹配异仓供需，输出候选调拨量=min(超额,缺口)，仅候选不能同时执行多个配对。',"WITH s AS (SELECT warehouse_id,product_id,SUM(-quantity_delta) sold FROM stock_movements WHERE movement_type='sale' AND movement_date BETWEEN '2025-12-02' AND '2025-12-31' GROUP BY warehouse_id,product_id), a AS (SELECT i.warehouse_id,i.product_id,i.quantity,COALESCE(s.sold,0) sold FROM inventory_snapshots i JOIN products p ON p.product_id=i.product_id LEFT JOIN s ON s.warehouse_id=i.warehouse_id AND s.product_id=i.product_id WHERE i.snapshot_date='2025-12-31' AND p.active=1), b AS (SELECT *,quantity-2*sold surplus,sold-quantity shortage FROM a) SELECT x.product_id,x.warehouse_id from_warehouse,y.warehouse_id to_warehouse,CASE WHEN x.surplus<y.shortage THEN x.surplus ELSE y.shortage END proposed_units FROM b x JOIN b y ON y.product_id=x.product_id AND y.warehouse_id<>x.warehouse_id WHERE x.surplus>=10 AND y.shortage>0 ORDER BY x.product_id,x.warehouse_id,y.warehouse_id",'商品×供给仓×需求仓','候选配对不等于完成调拨优化，同一库存可能被重复分配。','计算供需；自连接不同仓；取可行上限；注明非全局优化',True)
cross('销售＋库存','销售毛利与库存投资回报','2025年全部渠道，按类别计算净销售毛利与2024年底/2025年底平均库存标准价值，毛利/平均库存为库存投资回报倍数；保留全部类别。',"WITH a AS (SELECT p.category_id,SUM(s.net_cents-s.cost_cents) gross FROM v_sales_lines s JOIN products p ON p.product_id=s.product_id WHERE s.order_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY p.category_id), b AS (SELECT p.category_id,SUM(i.quantity*i.unit_cost_cents)/2.0 avg_stock FROM inventory_snapshots i JOIN products p ON p.product_id=i.product_id WHERE i.snapshot_date IN ('2024-12-31','2025-12-31') GROUP BY p.category_id) SELECT c.category_id,COALESCE(a.gross,0) gross_cents,b.avg_stock avg_stock_cents,ROUND(COALESCE(a.gross,0)/NULLIF(b.avg_stock,0),4) gmroi FROM categories c LEFT JOIN a ON a.category_id=c.category_id LEFT JOIN b ON b.category_id=c.category_id ORDER BY gmroi DESC,c.category_id",'类别','用销售收入替代毛利会变成另一个指标。','汇总类别毛利；汇总两端库存；计算回报并标明估算口径',True)
cross('库存＋采购','逾期在途与缺货叠加','截止2025年底，将已到期未足量收货采购行按仓库商品汇总；结合当前库存和近30日销量，筛选库存低于30日需求且逾期未收货量>0的商品。',"WITH p AS (SELECT warehouse_id,product_id,SUM(quantity_ordered-accepted) overdue FROM v_po_lines WHERE promised_date<='2025-12-31' AND accepted<quantity_ordered GROUP BY warehouse_id,product_id), s AS (SELECT warehouse_id,product_id,SUM(-quantity_delta) sold FROM stock_movements WHERE movement_type='sale' AND movement_date BETWEEN '2025-12-02' AND '2025-12-31' GROUP BY warehouse_id,product_id) SELECT i.warehouse_id,i.product_id,i.quantity,s.sold demand,p.overdue overdue_units,s.sold-i.quantity shortage FROM inventory_snapshots i JOIN p ON p.warehouse_id=i.warehouse_id AND p.product_id=i.product_id JOIN s ON s.warehouse_id=i.warehouse_id AND s.product_id=i.product_id WHERE i.snapshot_date='2025-12-31' AND i.quantity<s.sold ORDER BY shortage DESC,i.warehouse_id,i.product_id",'仓库×商品','将拒收库存算作可售库存会低估缺口。','汇总逾期缺口；汇总销售；匹配期末并排序')
cross('库存＋采购','收货入库完整性核对','比较每条合格收货记录与库存流水入库数量，包含拒收全部的记录；输出采购行、收货编号、应入库及已入库差额；仅差额非0。预计干净主库无差异，不能伪造异常。',"WITH a AS (SELECT receipt_id,SUM(quantity_delta) qty FROM stock_movements WHERE movement_type='receipt' GROUP BY receipt_id) SELECT g.receipt_id,g.po_item_id,g.quantity_received-g.quantity_rejected expected_units,COALESCE(a.qty,0) posted_units,COALESCE(a.qty,0)-(g.quantity_received-g.quantity_rejected) difference FROM goods_receipts g LEFT JOIN a ON a.receipt_id=g.receipt_id WHERE COALESCE(a.qty,0)<>g.quantity_received-g.quantity_rejected ORDER BY g.receipt_id",'收货记录','内连接会漏掉应入库但未记账的记录。','先聚合库存流水；与质检收货匹配；筛选差额；空结果也是成功')
cross('库存＋采购','供应商延迟与仓库资金压力','2025年到期采购行，按供应商计算逾期未接收金额；按商品仓库去重后汇总关联期末库存价值，仅纳入该供应商有逾期未足量收货的商品仓库；库存价值无法视为单一供应商独占。',"WITH a AS (SELECT supplier_id,warehouse_id,product_id,SUM((quantity_ordered-accepted)*unit_price_cents) overdue_value FROM v_po_lines WHERE promised_date BETWEEN '2025-01-01' AND '2025-12-31' AND quantity_ordered>accepted GROUP BY supplier_id,warehouse_id,product_id) SELECT a.supplier_id,COUNT(*) affected_pairs,SUM(a.overdue_value) overdue_cents,SUM(i.quantity*i.unit_cost_cents) exposed_stock_cents FROM a JOIN inventory_snapshots i ON i.warehouse_id=a.warehouse_id AND i.product_id=a.product_id AND i.snapshot_date='2025-12-31' GROUP BY a.supplier_id ORDER BY overdue_cents DESC,a.supplier_id",'供应商','跨供应商库存暴露值不可全局相加，可能重叠。','按供应商商品仓聚合；连接快照；汇总暴露值',True)
cross('销售＋财务','门店贡献利润与费用','2025年线下每门店，净销售-销售成本-归属于门店的费用分录作为贡献利润（未扣人工与总部费用，非净利润）；保留所有门店，输出贡献率。',"WITH a AS (SELECT store_id,SUM(net_cents) net,SUM(cost_cents) cost FROM v_sales_lines WHERE channel='store' AND order_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY store_id), b AS (SELECT store_id,SUM(expense_cents) expense FROM v_expenses WHERE entry_date BETWEEN '2025-01-01' AND '2025-12-31' AND store_id IS NOT NULL GROUP BY store_id) SELECT s.store_id,COALESCE(a.net,0) net_cents,COALESCE(a.cost,0) cost_cents,COALESCE(b.expense,0) expense_cents,COALESCE(a.net-a.cost,0)-COALESCE(b.expense,0) contribution_cents,ROUND(100.0*(COALESCE(a.net-a.cost,0)-COALESCE(b.expense,0))/NULLIF(a.net,0),2) contribution_pct FROM stores s LEFT JOIN a ON a.store_id=s.store_id LEFT JOIN b ON b.store_id=s.store_id ORDER BY contribution_cents DESC,s.store_id",'门店','费用不可按销售明细直接连接；贡献利润不是会计净利润。','独立收入成本与费用；合并门店；计算利润')
cross('销售＋财务','订单结算与收入核对','2025年全部已完成订单，支付成功金额减实际退款，比较净销售金额；输出存在差额的订单。退款本库即退款已支付，支付日期≤年底；失败支付不计。',"WITH a AS (SELECT order_id,SUM(amount_cents) paid FROM payments WHERE status='settled' AND payment_date<='2025-12-31' GROUP BY order_id), b AS (SELECT i.order_id,SUM(r.refund_cents) refunded FROM returns r JOIN order_items i ON i.order_item_id=r.order_item_id WHERE r.return_date<='2025-12-31' GROUP BY i.order_id) SELECT o.order_id,o.net_cents,COALESCE(a.paid,0)-COALESCE(b.refunded,0) cash_net_cents,COALESCE(a.paid,0)-COALESCE(b.refunded,0)-o.net_cents difference_cents FROM v_order_net o LEFT JOIN a ON a.order_id=o.order_id LEFT JOIN b ON b.order_id=o.order_id WHERE o.order_date BETWEEN '2025-01-01' AND '2025-12-31' AND COALESCE(a.paid,0)-COALESCE(b.refunded,0)<>o.net_cents ORDER BY o.order_id",'订单','使用所有付款状态或连接拆分付款导致重复。','聚合订单付款；聚合退款；对照订单净额；允许空结果')
cross('销售＋财务','门店月度收入与费用偏离','2025年每店每月，净销售、费用、费用率及过去3个月费用率（总费用/总净销售）；至少三个月才输出滚动率，缺失月份销售费用为0。',"WITH m AS (SELECT DISTINCT month_key FROM calendar_days WHERE month_key>='2025-01'), a AS (SELECT store_id,SUBSTR(order_date,1,7) m,SUM(net_cents) net FROM v_sales_lines WHERE channel='store' AND order_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY store_id,SUBSTR(order_date,1,7)), b AS (SELECT store_id,SUBSTR(entry_date,1,7) m,SUM(expense_cents) expense FROM v_expenses WHERE entry_date BETWEEN '2025-01-01' AND '2025-12-31' AND store_id IS NOT NULL GROUP BY store_id,SUBSTR(entry_date,1,7)), z AS (SELECT s.store_id,m.month_key,COALESCE(a.net,0) net,COALESCE(b.expense,0) expense FROM stores s CROSS JOIN m LEFT JOIN a ON a.store_id=s.store_id AND a.m=m.month_key LEFT JOIN b ON b.store_id=s.store_id AND b.m=m.month_key), p AS (SELECT *,SUM(net) OVER(PARTITION BY store_id ORDER BY month_key ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) n3,SUM(expense) OVER(PARTITION BY store_id ORDER BY month_key ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) e3,COUNT(*) OVER(PARTITION BY store_id ORDER BY month_key ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) k FROM z) SELECT store_id,month_key,net net_cents,expense expense_cents,ROUND(100.0*expense/NULLIF(net,0),2) expense_pct,CASE WHEN k=3 THEN ROUND(100.0*e3/NULLIF(n3,0),2) ELSE NULL END rolling_pct FROM p ORDER BY store_id,month_key",'门店×月','直接平均各月费用率不能得到整体费用率。','建立连续月份网格；连接两个独立汇总；窗口计算滚动率',True)
cross('采购＋财务','采购承诺、收货、开票及付款敞口','截至2025年底每供应商，采购订单金额、实际合格收货计价、发票金额、实付及未付余额；两套数据分别按供应商汇总，保留无采购供应商。',"WITH a AS (SELECT supplier_id,SUM(ordered_cents) ordered,SUM(accepted*unit_price_cents) received FROM v_po_lines GROUP BY supplier_id), b AS (SELECT supplier_id,SUM(billed_cents) billed,SUM(paid_cents) paid,SUM(balance_cents) balance FROM v_invoice_balance GROUP BY supplier_id) SELECT s.supplier_id,COALESCE(a.ordered,0) ordered_cents,COALESCE(a.received,0) received_cents,COALESCE(b.billed,0) billed_cents,COALESCE(b.paid,0) paid_cents,COALESCE(b.balance,0) balance_cents FROM suppliers s LEFT JOIN a ON a.supplier_id=s.supplier_id LEFT JOIN b ON b.supplier_id=s.supplier_id ORDER BY balance_cents DESC,s.supplier_id",'供应商','采购行和发票行直接连接会重复计入付款。','聚合采购行和发票余额；匹配供应商；形成资金敞口')
cross('采购＋财务','三方不一致且已经付款的发票','每采购单（本模拟正常一单一发票），实际接受数量按采购价计价，比较发票金额；找出金额差超过100分且已经付款的发票，并返回超付于合格收货金额的差值。',"WITH a AS (SELECT po_id,SUM(accepted*unit_price_cents) received FROM v_po_lines GROUP BY po_id) SELECT b.supplier_invoice_id,b.po_id,b.billed_cents,b.paid_cents,a.received received_cents,b.billed_cents-a.received bill_difference_cents,b.paid_cents-a.received paid_difference_cents FROM v_invoice_balance b JOIN a ON a.po_id=b.po_id WHERE b.paid_cents>0 AND ABS(b.billed_cents-a.received)>100 ORDER BY ABS(b.billed_cents-a.received) DESC,b.supplier_invoice_id",'发票','已付款不代表货物、价格、发票均一致。','聚合合格收货金额；关联付款余额；筛选差异')
cross('采购＋财务','供应商资金风险分层','2025年底，供应商逾期应付占未付总额比例、2025年到期订单行准时足量率；风险规则：逾期应付≥500000分且逾期占比>40%，或准时率<60%且≥10到期行；按应付降序。',"WITH a AS (SELECT supplier_id,SUM(CASE WHEN balance_cents>0 THEN balance_cents ELSE 0 END) outstanding,SUM(CASE WHEN balance_cents>0 AND due_date<'2025-12-31' THEN balance_cents ELSE 0 END) overdue FROM v_invoice_balance GROUP BY supplier_id), b AS (SELECT supplier_id,COUNT(*) n,SUM(CASE WHEN on_time>=quantity_ordered THEN 1 ELSE 0 END) good FROM v_po_lines WHERE promised_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY supplier_id), z AS (SELECT s.supplier_id,COALESCE(a.outstanding,0) outstanding,COALESCE(a.overdue,0) overdue,100.0*a.overdue/NULLIF(a.outstanding,0) overdue_pct,COALESCE(b.n,0) due_lines,100.0*b.good/NULLIF(b.n,0) ontime_pct FROM suppliers s LEFT JOIN a ON a.supplier_id=s.supplier_id LEFT JOIN b ON b.supplier_id=s.supplier_id) SELECT supplier_id,outstanding outstanding_cents,overdue overdue_cents,ROUND(overdue_pct,2) overdue_pct,due_lines,ROUND(ontime_pct,2) ontime_pct FROM z WHERE (overdue>=500000 AND overdue_pct>40) OR (due_lines>=10 AND ontime_pct<60) ORDER BY outstanding DESC,supplier_id",'供应商','不能以未到期应付代替逾期应付，也不能用零代替无历史履约。','独立计算账龄和履约；合并供应商；组合风险条件',True)
cross('电商＋财务','渠道广告后的贡献利润','2025年线上订单归因会话渠道，净销售、毛利减广告支出为广告后贡献；未分摊管理、人力或配送费用；按贡献率输出。',"WITH a AS (SELECT s.source_id,SUM(o.net_cents) net,SUM(o.net_cents-o.cost_cents) gross FROM v_order_net o JOIN customer_sessions s ON s.session_id=o.session_id WHERE o.channel='online' AND o.order_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY s.source_id), b AS (SELECT source_id,SUM(spend_cents) spend FROM marketing_campaigns WHERE month_key BETWEEN '2025-01' AND '2025-12' GROUP BY source_id) SELECT t.source_id,COALESCE(a.net,0) net_cents,COALESCE(a.gross,0) gross_cents,COALESCE(b.spend,0) spend_cents,COALESCE(a.gross,0)-COALESCE(b.spend,0) contribution_cents,ROUND(100.0*(COALESCE(a.gross,0)-COALESCE(b.spend,0))/NULLIF(a.net,0),2) contribution_pct FROM traffic_sources t LEFT JOIN a ON a.source_id=t.source_id LEFT JOIN b ON b.source_id=t.source_id ORDER BY contribution_cents DESC,t.source_id",'渠道','广告后毛利不等于公司净利润。','独立归因毛利与支出；连接渠道；计算贡献')
cross('电商＋财务','首购客户90天毛利与获客成本','按历史首次线上订单归因渠道及首购月份；只纳入截至年底有90日完整观察期客户；首购日起第0—89日的净毛利；对照该渠道该月广告支出/该月所有新客数（包括未成熟客户），求每人成熟期毛利和获客成本差额。',"WITH f AS (SELECT o.*,ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY order_date,order_id) rn FROM v_order_net o WHERE channel='online'), a AS (SELECT f.customer_id,f.order_date,d.day_index idx,s.source_id,SUBSTR(f.order_date,1,7) m FROM f JOIN customer_sessions s ON s.session_id=f.session_id JOIN calendar_days d ON d.day=f.order_date WHERE f.rn=1), n AS (SELECT source_id,m,COUNT(*) customers FROM a GROUP BY source_id,m), g AS (SELECT a.source_id,a.m,a.customer_id,SUM(o.net_cents-o.cost_cents) gross FROM a JOIN f o ON o.customer_id=a.customer_id JOIN calendar_days d ON d.day=o.order_date AND d.day_index BETWEEN a.idx AND a.idx+89 WHERE a.idx+89<=1095 GROUP BY a.source_id,a.m,a.customer_id), z AS (SELECT source_id,m,COUNT(*) mature,AVG(gross) avg_gross FROM g GROUP BY source_id,m) SELECT z.source_id,z.m cohort,z.mature,n.customers new_customers,ROUND(z.avg_gross,2) gross90_per_customer_cents,ROUND(1.0*p.spend_cents/n.customers,2) cac_cents,ROUND(z.avg_gross-1.0*p.spend_cents/n.customers,2) difference_cents FROM z JOIN n ON n.source_id=z.source_id AND n.m=z.m JOIN marketing_campaigns p ON p.source_id=z.source_id AND p.month_key=z.m ORDER BY z.source_id,z.m",'首购渠道×月','将未满90天客户也进入90天价值分母会产生右删失偏差。','确定首次订单与渠道；建立完整观察窗口；计算客户毛利；独立获客成本',True)
cross('电商＋财务','退款影响与渠道利润风险','2025年线上渠道，退款率=退款/折后退款前销售额，退货后毛利，以及退款前毛利估算（原销售成本加回退货原成本）；按退款率降序，分母为0返回NULL。',"WITH a AS (SELECT o.session_id,SUM(i.quantity*i.unit_price_cents-i.discount_cents) gross_revenue,SUM(i.quantity*i.unit_cost_cents) original_cost FROM orders o JOIN order_items i ON i.order_id=o.order_id WHERE o.channel='online' AND o.status='completed' AND o.order_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY o.session_id), b AS (SELECT session_id,SUM(net_cents) net,SUM(cost_cents) cost,SUM(refund_cents) refund FROM v_sales_lines WHERE channel='online' AND order_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY session_id) SELECT s.source_id,SUM(a.gross_revenue) before_refund_cents,SUM(b.refund) refund_cents,ROUND(100.0*SUM(b.refund)/NULLIF(SUM(a.gross_revenue),0),2) refund_pct,SUM(a.gross_revenue-a.original_cost) before_gross_cents,SUM(b.net-b.cost) after_gross_cents FROM customer_sessions s JOIN a ON a.session_id=s.session_id JOIN b ON b.session_id=s.session_id GROUP BY s.source_id ORDER BY refund_pct DESC,s.source_id",'渠道','只减退款不冲回退货成本会误算毛利。','会话内分别汇总原销售与净销售；连接会话渠道；比较前后毛利')
cross('人力＋销售','门店人效及人工占比','2025年线下门店，按员工月归属门店的人力成本、出勤+加班工时；销售每小时及人工占净销售比例；保留所有门店。',"WITH a AS (SELECT store_id,SUM(net_cents) net FROM v_sales_lines WHERE channel='store' AND order_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY store_id), b AS (SELECT store_id,SUM(labor_cents) labor,SUM(worked_minutes+overtime_minutes) minutes_worked FROM v_staff_month WHERE month_key BETWEEN '2025-01' AND '2025-12' AND store_id IS NOT NULL GROUP BY store_id) SELECT s.store_id,COALESCE(a.net,0) net_cents,COALESCE(b.labor,0) labor_cents,ROUND(1.0*COALESCE(b.minutes_worked,0)/60,2) worked_hours,ROUND(60.0*COALESCE(a.net,0)/NULLIF(b.minutes_worked,0),2) sales_per_hour_cents,ROUND(100.0*COALESCE(b.labor,0)/NULLIF(a.net,0),2) labor_pct FROM stores s LEFT JOIN a ON a.store_id=s.store_id LEFT JOIN b ON b.store_id=s.store_id ORDER BY s.store_id",'门店','不得使用当前归属替代历史岗位或重复累加月薪。','聚合历史岗位月成本；汇总销售；合并计算人效')
cross('人力＋销售','门店人员变化与销售变化诊断','2025年门店×月，月末在岗人数使用历史区间，月度净销售使用实际交易；计算环比人力及销售变化率，上月为0或缺失返回NULL；标记人数增加而销售下降。',"WITH m AS (SELECT month_key,MAX(day) last_day FROM calendar_days WHERE month_key>='2024-12' GROUP BY month_key), h AS (SELECT s.store_id,m.month_key,COUNT(e.employee_id) headcount FROM stores s CROSS JOIN m LEFT JOIN employment_history e ON e.store_id=s.store_id AND e.start_date<=m.last_day AND (e.end_date IS NULL OR e.end_date>m.last_day) GROUP BY s.store_id,m.month_key), a AS (SELECT store_id,SUBSTR(order_date,1,7) m,SUM(net_cents) net FROM v_sales_lines WHERE channel='store' AND order_date>='2024-12-01' GROUP BY store_id,SUBSTR(order_date,1,7)), z AS (SELECT h.*,COALESCE(a.net,0) net FROM h LEFT JOIN a ON a.store_id=h.store_id AND a.m=h.month_key), p AS (SELECT *,LAG(headcount) OVER(PARTITION BY store_id ORDER BY month_key) prev_h,LAG(net) OVER(PARTITION BY store_id ORDER BY month_key) prev_net FROM z) SELECT store_id,month_key,headcount,net net_cents,ROUND(100.0*(headcount-prev_h)/NULLIF(prev_h,0),2) headcount_change_pct,ROUND(100.0*(net-prev_net)/NULLIF(prev_net,0),2) sales_change_pct,CASE WHEN headcount>prev_h AND net<prev_net THEN 1 ELSE 0 END review_flag FROM p WHERE month_key>='2025-01' ORDER BY store_id,month_key",'门店×月','人力变动与销售变化相关并不证明因果。','重建历史人数；独立月份销售；窗口比较；生成复核标志',True)
cross('企业综合经营','月度经营汇总表','2025年每月全渠道净销售及毛利、费用分录、人工估算成本、广告支出、采购承诺金额；广告支出独立展示（不并入费用避免潜在双计）；经营贡献=毛利-费用-人工，不是净利润。',"WITH m AS (SELECT DISTINCT month_key FROM calendar_days WHERE month_key>='2025-01'), s AS (SELECT SUBSTR(order_date,1,7) m,SUM(net_cents) net,SUM(net_cents-cost_cents) gross FROM v_sales_lines WHERE order_date>='2025-01-01' GROUP BY SUBSTR(order_date,1,7)), f AS (SELECT SUBSTR(entry_date,1,7) m,SUM(expense_cents) expense FROM v_expenses WHERE entry_date>='2025-01-01' GROUP BY SUBSTR(entry_date,1,7)), h AS (SELECT month_key,SUM(labor_cents) labor FROM v_staff_month WHERE month_key>='2025-01' GROUP BY month_key), p AS (SELECT SUBSTR(order_date,1,7) m,SUM(ordered_cents) procurement FROM v_po_lines WHERE order_date>='2025-01-01' GROUP BY SUBSTR(order_date,1,7)), a AS (SELECT month_key,SUM(spend_cents) spend FROM marketing_campaigns WHERE month_key>='2025-01' GROUP BY month_key) SELECT m.month_key,COALESCE(s.net,0) net_cents,COALESCE(s.gross,0) gross_cents,COALESCE(f.expense,0) expense_cents,COALESCE(h.labor,0) labor_cents,COALESCE(a.spend,0) advertising_cents,COALESCE(p.procurement,0) committed_purchase_cents,COALESCE(s.gross,0)-COALESCE(f.expense,0)-COALESCE(h.labor,0) operating_contribution_cents FROM m LEFT JOIN s ON s.m=m.month_key LEFT JOIN f ON f.m=m.month_key LEFT JOIN h ON h.month_key=m.month_key LEFT JOIN p ON p.m=m.month_key LEFT JOIN a ON a.month_key=m.month_key ORDER BY m.month_key",'月','采购承诺不是费用，不能直接从当月利润扣除。','各模块独立汇总月份；连接月份轴；展示经营贡献及独立指标',True)
cross('企业综合经营','跨域季度风险评分与经营报告','2025年每季度，计算毛利率、费用率、人工率、供应商准时足量率、期末库存资金；风险项为毛利率<30%、费用率>50%、人工率>20%、履约<60%；保留所有季度，缺失不计风险并显示缺失指标数。使用月份映射，不将采购承诺算费用。',"WITH qm AS (SELECT DISTINCT month_key,CONCAT(SUBSTR(month_key,1,4),'-Q',CASE WHEN SUBSTR(month_key,6,2)<='03' THEN '1' WHEN SUBSTR(month_key,6,2)<='06' THEN '2' WHEN SUBSTR(month_key,6,2)<='09' THEN '3' ELSE '4' END) q FROM calendar_days WHERE month_key>='2025-01'), qs AS (SELECT q,MAX(month_key) end_m FROM qm GROUP BY q), s AS (SELECT qm.q,SUM(v.net_cents) net,SUM(v.net_cents-v.cost_cents) gross FROM v_sales_lines v JOIN qm ON qm.month_key=SUBSTR(v.order_date,1,7) GROUP BY qm.q), f AS (SELECT qm.q,SUM(v.expense_cents) expense FROM v_expenses v JOIN qm ON qm.month_key=SUBSTR(v.entry_date,1,7) GROUP BY qm.q), h AS (SELECT qm.q,SUM(v.labor_cents) labor FROM v_staff_month v JOIN qm ON qm.month_key=v.month_key GROUP BY qm.q), p AS (SELECT qm.q,COUNT(*) n,SUM(CASE WHEN v.on_time>=v.quantity_ordered THEN 1 ELSE 0 END) good FROM v_po_lines v JOIN qm ON qm.month_key=SUBSTR(v.promised_date,1,7) GROUP BY qm.q), i AS (SELECT SUBSTR(snapshot_date,1,7) m,SUM(quantity*unit_cost_cents) stock FROM inventory_snapshots GROUP BY SUBSTR(snapshot_date,1,7)), z AS (SELECT qs.q,s.net,100.0*s.gross/NULLIF(s.net,0) margin,100.0*COALESCE(f.expense,0)/NULLIF(s.net,0) expense_pct,100.0*COALESCE(h.labor,0)/NULLIF(s.net,0) labor_pct,100.0*p.good/NULLIF(p.n,0) delivery,i.stock FROM qs LEFT JOIN s ON s.q=qs.q LEFT JOIN f ON f.q=qs.q LEFT JOIN h ON h.q=qs.q LEFT JOIN p ON p.q=qs.q LEFT JOIN i ON i.m=qs.end_m) SELECT q,net net_cents,ROUND(margin,2) margin_pct,ROUND(expense_pct,2) expense_pct,ROUND(labor_pct,2) labor_pct,ROUND(delivery,2) delivery_pct,stock stock_cents,CASE WHEN margin<30 THEN 1 ELSE 0 END+CASE WHEN expense_pct>50 THEN 1 ELSE 0 END+CASE WHEN labor_pct>20 THEN 1 ELSE 0 END+CASE WHEN delivery<60 THEN 1 ELSE 0 END risk_count,CASE WHEN margin IS NULL THEN 1 ELSE 0 END+CASE WHEN expense_pct IS NULL THEN 1 ELSE 0 END+CASE WHEN labor_pct IS NULL THEN 1 ELSE 0 END+CASE WHEN delivery IS NULL THEN 1 ELSE 0 END missing_count FROM z ORDER BY q",'季度','跨不同粒度连表会夸大指标；风险评分不是财务审计结论。','建立季度轴；独立汇总各域；连接季度末库存；计算指标和风险',True)
assert len(T)==50
